import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, capacity, cost, rev;
        Edge(int to, int capacity, int cost, int rev) {
            this.to = to;
            this.capacity = capacity;
            this.cost = cost;
            this.rev = rev;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int K = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(st.nextToken());

        int[] a = new int[K];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < K; i++) {
            a[i] = Integer.parseInt(st.nextToken()) - 1;
        }

        Pair[] b = new Pair[m];
        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken()) - 1;
            int y = Integer.parseInt(st.nextToken()) - 1;
            b[i] = new Pair(x, y);
        }

        int totalNodes = n * 105 + 2;
        int s = totalNodes - 2;
        int t = totalNodes - 1;

        List<List<Edge>> graph = new ArrayList<>();
        for (int i = 0; i < totalNodes; i++) {
            graph.add(new ArrayList<>());
        }

        // Helper method to add edges
        BiConsumer<Integer, Edge> addEdge = (u, e) -> {
            graph.get(u).add(e);
        };

        // Function to add edges
        java.util.function.BiConsumer<Integer, Integer[]> addEdgeFunc = (u, vArr) -> {
            int v = vArr[0];
            int cap = vArr[1];
            int cost = vArr[2];
            int rev = vArr[3];
            graph.get(u).add(new Edge(v, cap, cost, rev));
        };

        // Since Java doesn't support lambda with multiple statements easily, define a method
        // Instead, define a method to add edges
        // But for simplicity, define a method outside main

        // Map to store id
        int[][] id = new int[n][105];
        int nodeCounter = 0;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= 100; j++) {
                id[i][j] = nodeCounter++;
            }
        }

        // Method to add edges
        // Since Java doesn't support lambda with multiple statements easily, define a static method
        // outside main

        // Add edges from source to initial nodes
        for (int i = 0; i < K; i++) {
            addEdge(graph, s, new Edge(id[a[i]][0], 1, 0, graph.get(id[a[i]][0]).size()));
        }

        // Add edges from layer 0 to sink
        for (int i = 0; i <= 100; i++) {
            addEdge(graph, id[0][i], new Edge(t, K, C * i, graph.get(t).size()));
        }

        // Add edges for layer progression
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < 100; j++) {
                addEdge(graph, id[i][j], new Edge(id[i][j + 1], K, 0, graph.get(id[i][j + 1]).size()));
            }
        }

        // Add edges for b
        for (Pair edge : b) {
            int x = edge.x;
            int y = edge.y;
            for (int j = 0; j < 100; j++) {
                for (int k = 0; k < K; k++) {
                    addEdge(graph, id[x][j], new Edge(id[y][j + 1], 1, D * (2 * k + 1), graph.get(id[y][j + 1]).size()));
                    addEdge(graph, id[y][j], new Edge(id[x][j + 1], 1, D * (2 * k + 1), graph.get(id[x][j + 1]).size()));
                }
            }
        }

        int totalFlow = 0;
        int totalCost = 0;
        int[] dist = new int[totalNodes];
        int[] potential = new int[totalNodes];
        int[] parentNode = new int[totalNodes];
        int[] parentEdge = new int[totalNodes];

        final int INF = Integer.MAX_VALUE;

        while (true) {
            Arrays.fill(dist, INF);
            dist[s] = 0;
            PriorityQueue<Pair> pq = new PriorityQueue<>(Comparator.comparingInt(p -> p.d));
            pq.offer(new Pair(0, s));
            while (!pq.isEmpty()) {
                Pair p = pq.poll();
                int d = p.d;
                int u = p.u;
                if (d > dist[u]) continue;
                for (int i = 0; i < graph.get(u).size(); i++) {
                    Edge e = graph.get(u).get(i);
                    if (e.capacity > 0 && dist[e.to] > dist[u] + e.cost + potential[u] - potential[e.to]) {
                        dist[e.to] = dist[u] + e.cost + potential[u] - potential[e.to];
                        parentNode[e.to] = u;
                        parentEdge[e.to] = i;
                        pq.offer(new Pair(dist[e.to], e.to));
                    }
                }
            }
            if (dist[t] == INF) break;
            for (int i = 0; i < totalNodes; i++) {
                potential[i] += dist[i];
            }
            int flowIncrement = Integer.MAX_VALUE;
            for (int u = t; u != s; u = parentNode[u]) {
                flowIncrement = Math.min(flowIncrement, graph.get(parentNode[u]).get(parentEdge[u]).capacity);
            }
            for (int u = t; u != s; u = parentNode[u]) {
                Edge e = graph.get(parentNode[u]).get(parentEdge[u]);
                e.capacity -= flowIncrement;
                graph.get(u).get(e.rev).capacity += flowIncrement;
            }
            totalFlow += flowIncrement;
            totalCost += flowIncrement * potential[t];
        }

        System.out.println(totalCost);
    }

    static class Pair {
        int d, u;
        Pair(int d, int u) {
            this.d = d;
            this.u = u;
        }
    }

    static class Pair {
        int x, y;
        Pair(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    static void addEdge(List<List<Edge>> graph, int u, Edge e) {
        graph.get(u).add(e);
    }
}
